/* Generated by tools/build.js from data/cissp.js. Edit that file, not this one. */
CertHub.addQuestions("cissp", [["cs1",0,1,"A security manager discovers that a proposed marketing initiative will create risk above the organization's stated risk appetite. What should the manager do FIRST?",["Present the risk and options to senior management so the business owner can make an informed decision","Block the initiative until controls reduce the risk","Accept the risk on behalf of the organization","Purchase cyber insurance to transfer the risk"],0,"Security advises; senior management owns risk decisions. Informing them with options is the manager's role.","Outline 1.10"],["cs2",0,1,"Under the ISC2 Code of Ethics, which canon takes precedence when canons conflict?",["Provide diligent and competent service to principals","Protect society, the common good, necessary public trust and confidence, and the infrastructure","Advance and protect the profession","Act honorably, honestly, justly, responsibly and legally"],1,"The canons are in priority order, and protecting society comes first.","Outline 1.1"],["cs3",0,1,"An asset worth $200,000 has an exposure factor of 25% and is expected to be hit once every four years. What is the annualized loss expectancy?",["$50,000","$200,000","$12,500","$800,000"],2,"SLE = 200,000 x 0.25 = 50,000; ARO = 0.25; ALE = 50,000 x 0.25 = 12,500.","Outline 1.10"],["cs4",0,1,"Which activity BEST demonstrates due diligence before signing a contract with a new cloud provider?",["Encrypting data after migration","Signing the contract with a standard SLA","Training staff on the new service","Reviewing the provider's SOC 2 Type II report and security practices"],3,"Due diligence is researching and understanding risk before acting; reviewing assurance reports does that.","Outline 1.3"],["cs5",0,1,"When developing a business continuity plan, what should be done FIRST?",["Obtain senior management support and define the scope","Conduct a business impact analysis","Select an alternate processing site","Test the recovery procedures"],0,"Without management backing and a defined scope, the BIA and later steps lack authority and resources.","Outline 1.8"],["cs6",0,1,"Which document is MANDATORY and specifies a particular technology or configuration required across the organization?",["Guideline","Standard","Policy","Baseline recommendation"],1,"Standards are mandatory and specific; policies are high level and guidelines are optional advice.","Outline 1.7"],["cs7",0,1,"The maximum amount of time a business process can be unavailable before the organization suffers unacceptable harm is called the:",["Recovery point objective (RPO)","Mean time to repair (MTTR)","Maximum tolerable downtime (MTD)","Work recovery time (WRT)"],2,"MTD is the upper limit; RTO must be set below it.","Outline 1.8"],["cs8",0,1,"An organization buys cyber insurance to cover losses from a data breach. Which risk response is this?",["Avoidance","Mitigation","Acceptance","Transference"],3,"Insurance shifts the financial impact to a third party, which is risk transfer.","Outline 1.10"],["cs9",0,1,"Which threat modeling method categorizes threats as spoofing, tampering, repudiation, information disclosure, denial of service and elevation of privilege?",["STRIDE","PASTA","DREAD","OCTAVE"],0,"STRIDE is Microsoft's threat categorization model.","Outline 1.11"],["cs10",0,1,"What is the BEST way to reduce the risk of fraud by an employee who controls both vendor creation and payment approval?",["Increase the employee's background check depth","Separate those duties between different employees","Require annual ethics training","Install cameras in the accounting office"],1,"Separation of duties prevents one person from completing a fraudulent transaction alone.","Outline 1.9"],["cs11",0,1,"A company wants to ensure its security program supports the organization's goals. What is MOST important?",["Adopting the latest security technologies","Maximizing the number of controls implemented","Aligning security governance with business strategy, goals and mission","Matching the security budget of competitors"],2,"Governance exists to support business objectives, not technology for its own sake.","Outline 1.3"],["cs12",0,1,"Personal data is being transferred from the EU to a processor in another country. What should the security professional ensure FIRST?",["That the data is encrypted with AES-256","That the processor has a firewall","That the transfer is logged in the SIEM","That a lawful transfer mechanism, such as an adequacy decision or standard contractual clauses, is in place"],3,"Transborder data flow is a legal requirement first; technical controls come after legal compliance.","Outline 1.4"],["cs13",0,1,"Which is the MOST important measure of a security awareness program's effectiveness?",["A reduction in security incidents caused by user behavior","Percentage of staff completing training","Number of training modules produced","Positive employee feedback surveys"],0,"Effectiveness is shown by changed behavior and outcomes, not completion counts.","Outline 1.13"],["cs14",0,1,"When a supplier provides critical software components, which control BEST addresses supply chain risk?",["Rejecting all third-party software","Contractual security requirements with the right to audit and ongoing supplier assessment","Relying on the supplier's marketing materials","Scanning the supplier's website for vulnerabilities once"],1,"Supply chain risk management needs contractual requirements and continuous assessment of the supplier.","Outline 1.12"],["cs15",0,2,"Who is ultimately responsible for determining the classification of a data set?",["The data custodian","The system administrator","The data owner","The chief information security officer"],2,"The owner, a senior business manager, is accountable for classifying and protecting the data.","Outline 2.1"],["cs16",0,2,"An organization will reuse solid-state drives that stored confidential data. Which method is MOST appropriate?",["Formatting the drive","Degaussing the drive","Deleting the files and emptying the recycle bin","Cryptographic erase or manufacturer secure erase"],3,"SSDs are not magnetic and wear leveling defeats overwriting; purge via secure or cryptographic erase is appropriate.","Outline 2.4"],["cs17",0,2,"What is the PRIMARY purpose of data classification?",["To apply protection proportional to the data's value and sensitivity","To reduce the number of files stored","To comply with encryption export laws","To identify which employees created the data"],0,"Classification drives consistent, cost-effective protection and handling requirements.","Outline 2.1"],["cs18",0,2,"Under GDPR terminology, a payroll company that processes employee data on behalf of a client is the:",["Data controller","Data processor","Data subject","Data owner"],1,"The processor acts on behalf of the controller, who determines purposes and means.","Outline 2.2"],["cs19",0,2,"Which role is responsible for day-to-day implementation of the protection controls specified for data?",["Data owner","Data subject","Data custodian","Auditor"],2,"Custodians (often IT) implement and maintain controls on the owner's behalf.","Outline 2.2"],["cs20",0,2,"An organization adopts a NIST control baseline and removes controls that do not apply to its systems. This is called:",["Tailoring","Baselining","Benchmarking","Scoping"],3,"Scoping removes inapplicable controls; tailoring adjusts the remaining ones.","Outline 2.6"],["cs21",0,2,"What is the BEST reason to limit data collection to only what is necessary?",["It reduces the impact of a breach and supports privacy compliance","It makes backups faster","It eliminates the need for encryption","It removes the need for classification"],0,"Data minimization lowers exposure and aligns with privacy principles.","Outline 2.3"],["cs22",0,2,"Which control BEST protects sensitive data while it is being processed in memory?",["Full-disk encryption","Confidential computing using a trusted execution environment","TLS 1.3","Data retention schedules"],1,"Data in use is protected by secure enclaves or TEEs; disk encryption and TLS cover rest and transit.","Outline 2.6"],["cs23",0,2,"A company holds customer records well beyond any legal or business requirement. What is the GREATEST risk?",["Higher backup licensing costs","Slower database queries","Increased liability and exposure if the data is breached or subject to discovery","Reduced disk space for new projects"],2,"Over-retention increases legal and breach exposure; retention should follow a defined schedule.","Outline 2.4"],["cs24",0,3,"Which security model prevents a subject at the Secret level from writing information to an Unclassified object?",["Biba","Clark-Wilson","Brewer-Nash","Bell-LaPadula"],3,"Bell-LaPadula's star property (no write down) protects confidentiality.","Outline 3.2"],["cs25",0,3,"Which model is designed to prevent conflicts of interest, such as a consultant accessing data of competing clients?",["Brewer-Nash (Chinese Wall)","Bell-LaPadula","Biba","Take-Grant"],0,"Brewer-Nash dynamically restricts access based on previously accessed data sets.","Outline 3.2"],["cs26",0,3,"Which Biba rule prevents a high-integrity process from reading low-integrity data?",["Star integrity property (no write up)","Simple integrity property (no read down)","Simple security property (no read up)","Discretionary security property"],1,"Biba's simple integrity property stops reading lower-integrity data that could corrupt the subject.","Outline 3.2"],["cs27",0,3,"Which cryptographic mechanism provides integrity, authentication and non-repudiation of a message?",["Symmetric encryption","Message digest alone","Digital signature","Key escrow"],2,"A signature made with the sender's private key proves origin and integrity and cannot be repudiated.","Outline 3.6"],["cs28",0,3,"An attacker measures power consumption of a smart card to recover its key. This is a:",["Brute-force attack","Birthday attack","Replay attack","Side-channel attack"],3,"Side-channel attacks exploit physical emissions like power, timing or electromagnetic leakage.","Outline 3.7"],["cs29",0,3,"A physical door must be designed for the case where power fails. For an emergency exit in an occupied building, what should it do?",["Fail open (fail-safe) to allow people to exit","Fail secure to protect assets","Lock and trigger an alarm","Remain in its last state"],0,"Life safety always takes priority over asset protection.","Outline 3.9"],["cs30",0,3,"Which fire suppression system is MOST suitable for a data center to reduce accidental water discharge?",["Wet pipe sprinkler system","Pre-action sprinkler system","Deluge system","Handheld Class A extinguishers only"],1,"Pre-action requires a detection event before the pipes fill, reducing accidental discharge.","Outline 3.9"],["cs31",0,3,"What is the MOST important factor in the strength of a cryptographic implementation?",["Secrecy of the algorithm","Length of the ciphertext","Protection and management of the keys","Speed of the encryption"],2,"Kerckhoffs's principle: security should rest on the key, so key management is critical.","Outline 3.6"],["cs32",0,3,"Which component provides hardware-based secure key storage and platform integrity measurements on a laptop?",["BIOS password","Hypervisor","Memory management unit","Trusted Platform Module (TPM)"],3,"The TPM stores keys and measures boot components for attestation.","Outline 3.4"],["cs33",0,3,"An organization runs industrial control systems that cannot be patched. What is the BEST compensating control?",["Isolating the systems in a segmented network with strict access control and monitoring","Replacing the systems immediately regardless of cost","Installing antivirus on the PLCs","Disabling all logging to improve performance"],0,"Segmentation and monitoring reduce exposure when patching is not possible.","Outline 3.5"],["cs34",0,3,"Which secure design principle is violated when a new application ships with all features and admin interfaces enabled?",["Separation of duties","Secure defaults","Keep it simple","Shared responsibility"],1,"Systems should ship in their most secure configuration, with features enabled only when needed.","Outline 3.1"],["cs35",0,3,"Two users need to exchange a symmetric key over an untrusted network without prior contact. Which algorithm is designed for this?",["AES","SHA-256","Diffie-Hellman","3DES"],2,"Diffie-Hellman key agreement lets parties establish a shared secret over an insecure channel.","Outline 3.6"],["cs36",0,4,"At which OSI layer does a router make forwarding decisions based on IP addresses?",["Data link layer (Layer 2)","Transport layer (Layer 4)","Session layer (Layer 5)","Network layer (Layer 3)"],3,"IP addressing and routing occur at Layer 3.","Outline 4.1"],["cs37",0,4,"Which protocol suite provides confidentiality and integrity for traffic at the network layer between two sites?",["IPsec","TLS","SSH","SNMPv2c"],0,"IPsec operates at Layer 3 and is the standard for site-to-site VPNs.","Outline 4.1"],["cs38",0,4,"In IPsec, which protocol provides encryption of the payload?",["Authentication Header (AH)","Encapsulating Security Payload (ESP)","Internet Key Exchange (IKE)","Generic Routing Encapsulation (GRE)"],1,"ESP provides confidentiality; AH provides integrity and authentication only.","Outline 4.1"],["cs39",0,4,"An organization wants to stop attackers from moving laterally between workloads in its data center. What is the BEST approach?",["Add a larger perimeter firewall","Increase internet bandwidth","Implement micro-segmentation with policy enforced per workload","Deploy a CDN"],2,"Micro-segmentation controls east-west traffic between workloads.","Outline 4.1"],["cs40",0,4,"Which wireless security configuration is MOST appropriate for a corporate network?",["WPA2-Personal with a strong passphrase","WEP with MAC filtering","An open network with a captive portal","WPA3-Enterprise with 802.1X authentication"],3,"Enterprise mode gives per-user authentication and revocation.","Outline 4.1"],["cs41",0,4,"Which device inspects traffic inline and can automatically block detected attacks?",["Intrusion prevention system","Intrusion detection system","Network tap","Protocol analyzer"],0,"IPS sits inline and blocks; IDS only alerts.","Outline 4.2"],["cs42",0,4,"What is the BEST mitigation for a large volumetric DDoS attack against a public website?",["Adding more RAM to the web server","Contracting an upstream DDoS scrubbing service or CDN","Blocking ICMP at the host firewall","Increasing log retention"],1,"Volumetric attacks saturate links before on-premises controls can help, so mitigation must be upstream.","Outline 4.2"],["cs43",0,4,"Which control verifies a device's health and identity before allowing it onto the network?",["Proxy server","Load balancer","Network access control (NAC)","DNS sinkhole"],2,"NAC checks posture and authentication before granting network access.","Outline 4.2"],["cs44",0,4,"Which protocol should replace Telnet for remote administration?",["FTP","rlogin","SNMPv1","SSH"],3,"SSH encrypts the session, including credentials; Telnet sends them in cleartext.","Outline 4.3"],["cs45",0,4,"Which technology is MOST effective at protecting DNS responses from being forged?",["DNSSEC","DNS over UDP","Split-horizon DNS","Round-robin DNS"],0,"DNSSEC signs DNS records so resolvers can verify authenticity and integrity.","Outline 4.2"],["cs46",0,4,"A company is connecting a third-party vendor to its network for support. What is the BEST approach?",["Give the vendor a standard employee VPN account","Provide restricted, monitored access to only the required systems under a signed agreement","Allow direct RDP from the internet","Share an administrator password by email"],1,"Third-party connectivity should be least privilege, contractual and monitored.","Outline 4.3"],["cs47",0,4,"Which converged protocol carries SCSI storage commands over IP networks and should be isolated on its own network?",["VoIP","SIP","iSCSI","MPLS"],2,"iSCSI carries storage traffic over IP and should be segmented and authenticated.","Outline 4.1"],["cs48",0,5,"An employee transfers from finance to marketing but keeps finance system access. What is this called?",["Privilege escalation","Account takeover","Session hijacking","Privilege creep"],3,"Accumulated access from role changes is privilege creep; access reviews and mover processes prevent it.","Outline 5.5"],["cs49",0,5,"What is the BEST control to detect inappropriate accumulated access rights?",["Periodic user access reviews by managers or data owners","Longer password requirements","Annual security awareness training","Account lockout thresholds"],0,"Recertification catches access that is no longer needed.","Outline 5.5"],["cs50",0,5,"Which access control model assigns permissions based on job function?",["Mandatory access control (MAC)","Role-based access control (RBAC)","Discretionary access control (DAC)","Rule-based access control"],1,"RBAC ties permissions to roles that map to job functions.","Outline 5.4"],["cs51",0,5,"Which model uses security labels and clearances enforced by the system rather than the data owner?",["Discretionary access control (DAC)","Role-based access control (RBAC)","Mandatory access control (MAC)","Attribute-based access control (ABAC)"],2,"In MAC the system enforces label-based decisions; users cannot change them.","Outline 5.4"],["cs52",0,5,"A user logs in once and gains access to several web applications from different organizations using SAML. What is this?",["Kerberos realm trust","Password synchronization","Local account mapping","Federated identity"],3,"Federation lets identity from one organization's IdP be trusted by another's service provider.","Outline 5.3"],["cs53",0,5,"Which protocol is an identity layer built on OAuth 2.0?",["OpenID Connect","SAML 2.0","LDAP","RADIUS"],0,"OIDC adds authentication (ID tokens) on top of OAuth 2.0 authorization.","Outline 5.3"],["cs54",0,5,"In Kerberos, what does the Key Distribution Center issue after initial authentication?",["A SAML assertion","A ticket-granting ticket","An X.509 certificate","A one-time password"],1,"The authentication service issues a TGT used to request service tickets.","Outline 5.6"],["cs55",0,5,"When comparing biometric systems, which metric is the BEST single indicator of accuracy?",["False acceptance rate alone","Enrollment time","Crossover error rate (CER)","Throughput rate"],2,"CER is where FAR equals FRR; lower is more accurate.","Outline 5.6"],["cs56",0,5,"What is the MOST important step when an employee is terminated for cause?",["Delete the user's mailbox immediately","Collect the badge a week later","Send a company-wide announcement","Disable the user's access at or before the time they are notified"],3,"Access removal must be timely to prevent retaliation; data may need to be retained.","Outline 5.5"],["cs57",0,5,"Administrators should hold elevated rights only when approved and for a limited time. Which approach does this describe?",["Just-in-time privileged access","Single sign-on","Discretionary access control","Password vaulting without checkout"],0,"JIT removes standing privilege, reducing attack surface.","Outline 5.2"],["cs58",0,5,"Which combination is true multifactor authentication?",["A password and a security question","A password and a hardware token code","A fingerprint and a palm scan","A PIN and a passphrase"],1,"MFA requires different factor types: something you know plus something you have.","Outline 5.2"],["cs59",0,5,"Which centralized AAA protocol encrypts the entire payload and separates authentication, authorization and accounting?",["RADIUS","PAP","TACACS+","LDAP"],2,"TACACS+ uses TCP, encrypts the full body and separates AAA functions; RADIUS encrypts only the password.","Outline 5.6"],["cs60",0,6,"What must be obtained BEFORE beginning a penetration test?",["A list of known vulnerabilities","Administrator passwords for all systems","Approval from the internet service provider","Written authorization from management with authority over the systems"],3,"Testing without written permission may be illegal and violates ethics.","Outline 6.2"],["cs61",0,6,"A customer wants assurance that a vendor's controls operated effectively over the past year. Which report should they request?",["SOC 2 Type II","SOC 2 Type I","SOC 1 Type I","SOC 3"],0,"Type II tests operating effectiveness over a period; SOC 2 covers security controls.","Outline 6.5"],["cs62",0,6,"Which technique proactively tests an application's availability by running scripted user actions?",["Real user monitoring","Synthetic transactions","Log review","Static code analysis"],1,"Synthetic monitoring simulates users to detect issues before real users are affected.","Outline 6.2"],["cs63",0,6,"Which testing technique sends malformed or random input to find crashes and unexpected behavior?",["Static analysis","Code review","Fuzzing","Regression testing"],2,"Fuzz testing uses invalid or random input to find robustness issues.","Outline 6.2"],["cs64",0,6,"A penetration tester is given full network diagrams and source code. What type of test is this?",["Black box (zero knowledge)","Gray box (partial knowledge)","Blind test","White box (full knowledge)"],3,"White-box testers have complete information about the target.","Outline 6.2"],["cs65",0,6,"What is the PRIMARY purpose of an independent third-party audit?",["To provide objective assurance to stakeholders about controls","To fix vulnerabilities found internally","To replace internal testing","To train the security team"],0,"Independence gives objectivity and credibility to the findings.","Outline 6.1"],["cs66",0,6,"After a vulnerability assessment, what should the security manager do FIRST with the results?",["Patch every finding immediately","Prioritize findings by risk to the business and assign remediation owners","Share the raw scan output with all staff","Rerun the scan with more plugins"],1,"Results must be analyzed and risk-ranked so resources go to the most important issues.","Outline 6.4"],["cs67",0,6,"Which metric is a key risk indicator rather than a key performance indicator?",["Number of training sessions delivered","Help desk tickets closed per week","Number of critical vulnerabilities older than 30 days","Firewall uptime percentage"],2,"KRIs signal rising risk exposure; aging critical vulnerabilities indicate growing risk.","Outline 6.3"],["cs68",0,6,"Why should backup restoration be tested regularly?",["To reduce storage costs","To satisfy antivirus requirements","To remove old backup media","To verify data can actually be recovered within the required objectives"],3,"Untested backups may fail when needed; restore tests prove RTO and RPO can be met.","Outline 6.3"],["cs69",0,6,"Which type of scan gives the MOST accurate view of missing patches on a server?",["Credentialed (authenticated) scan","Unauthenticated external scan","Ping sweep","Banner grab"],0,"Authenticated scans can inspect installed software and configurations directly.","Outline 6.2"],["cs70",0,7,"During an incident, what is the FIRST priority?",["Preserving evidence","Ensuring the safety of people","Restoring operations","Notifying the media"],1,"Human life and safety always come first.","Outline 7.15"],["cs71",0,7,"What is the PRIMARY purpose of chain of custody documentation?",["To speed up forensic analysis","To identify the attacker","To prove evidence has been handled properly and not altered","To reduce storage requirements"],2,"Chain of custody establishes integrity and admissibility of evidence.","Outline 7.1"],["cs72",0,7,"Which order of volatility should a forensic investigator follow when collecting evidence?",["Disk, RAM, archived media, CPU cache","Archived media, disk, RAM, CPU cache","RAM, archived media, disk, CPU cache","CPU cache and registers, RAM, disk, archived media"],3,"Collect the most volatile data first because it is lost soonest.","Outline 7.1"],["cs73",0,7,"Which recovery site provides the fastest recovery but at the highest cost?",["Hot site","Warm site","Cold site","Mobile site"],0,"Hot sites are fully equipped with current data and can take over quickly.","Outline 7.10"],["cs74",0,7,"Which DR test runs the recovery site's systems while the primary site continues normal operation?",["Full interruption test","Parallel test","Read-through test","Walkthrough test"],1,"Parallel tests process real work at the alternate site without shutting down production.","Outline 7.12"],["cs75",0,7,"Which backup type copies all changes since the last full backup and does NOT reset the archive bit?",["Incremental","Full","Differential","Copy-on-write snapshot"],2,"Differential backups grow until the next full backup; restore needs the full plus the latest differential.","Outline 7.10"],["cs76",0,7,"Job rotation is MOST effective at which of the following?",["Improving system performance","Reducing licensing costs","Preventing malware infections","Detecting fraud and collusion"],3,"Another person performing the role may uncover irregularities.","Outline 7.4"],["cs77",0,7,"A critical patch is released for a production database. What should the security manager do FIRST?",["Test the patch and apply it through the change management process","Install it immediately on all production servers","Wait for the next annual maintenance window","Disable the database until the vendor confirms stability"],0,"Patches should be tested and approved to avoid outages, with urgency matched to risk.","Outline 7.8"],["cs78",0,7,"What is the MOST important output of the lessons-learned phase of incident response?",["A list of employees to discipline","Improvements to plans, controls and training to prevent recurrence","Deleting logs from the incident","A press release"],1,"Lessons learned exists to improve the program.","Outline 7.6"],["cs79",0,7,"Which tool automates response actions across security products based on playbooks?",["SIEM without automation","NetFlow collector","SOAR","Vulnerability scanner"],2,"SOAR orchestrates and automates response workflows.","Outline 7.2"],["cs80",0,7,"An employee traveling abroad is forced to open a secure facility under threat. Which control lets them signal this covertly?",["A mantrap","Security awareness training","Badge readers with PINs","A duress code or alarm"],3,"Duress signals alert security silently while appearing to comply.","Outline 7.15"],["cs81",0,7,"Which is the BEST way to keep server configurations from drifting from approved settings?",["Automated configuration management against a documented baseline","Manual checks once a year","Allowing administrators to change settings as needed","Rebuilding servers only after incidents"],0,"Baselines with automated enforcement detect and correct drift.","Outline 7.3"],["cs82",0,8,"When is the MOST cost-effective time to address security in the software development lifecycle?",["During user acceptance testing","During requirements and design","After deployment to production","During decommissioning"],1,"Defects found early are much cheaper to fix than later in the lifecycle.","Outline 8.1"],["cs83",0,8,"What is the BEST defense against SQL injection?",["Web application firewall only","Encrypting the database","Parameterized queries (prepared statements)","Hiding error messages"],2,"Parameterized queries keep data separate from code; WAFs are compensating controls.","Outline 8.5"],["cs84",0,8,"Which testing approach analyzes source code without executing it?",["Dynamic application security testing (DAST)","Penetration testing","Load testing","Static application security testing (SAST)"],3,"SAST reviews code at rest; DAST tests the running application.","Outline 8.2"],["cs85",0,8,"An organization wants to find known-vulnerable open-source libraries in its applications. Which tool is BEST?",["Software composition analysis (SCA)","DAST scanner","Network vulnerability scanner","Fuzzer"],0,"SCA inventories third-party components and flags known vulnerabilities and license issues.","Outline 8.2"],["cs86",0,8,"Which attack tricks an authenticated user's browser into submitting an unwanted request to a trusted site?",["Cross-site scripting (XSS)","Cross-site request forgery (CSRF)","SQL injection","Buffer overflow"],1,"CSRF abuses the site's trust in the user's browser; anti-CSRF tokens mitigate it.","Outline 8.5"],["cs87",0,8,"Before buying a commercial SaaS application for sensitive data, what should the security manager do FIRST?",["Run a penetration test on the vendor's production systems","Ask developers to review the vendor's source code","Assess the vendor's security posture and contractual commitments","Deploy the application to production to evaluate it"],2,"Acquired software risk is managed through vendor assessment and contracts; testing a vendor's systems needs their permission.","Outline 8.4"],["cs88",0,8,"Why should developers NOT have access to deploy code directly into production?",["It improves code performance","It reduces the need for testing","It is required for agile methodologies","It enforces separation of duties and change control"],3,"Separating development from production prevents unauthorized or untested changes.","Outline 8.1"],["cs89",0,8,"Which maturity model is specifically designed to assess and improve an organization's software security practices?",["OWASP SAMM","ITIL","COBIT","ISO 9001"],0,"SAMM measures software assurance maturity and guides improvement.","Outline 8.1"],["cs90",0,8,"What is the BEST way to integrate security testing into a DevSecOps pipeline?",["Run a manual penetration test before each commit","Automate security checks as gates in the CI/CD pipeline","Test security only annually","Rely on production monitoring to find flaws"],1,"Automated gates give fast, consistent feedback without slowing delivery.","Outline 8.3"]]);
